310: function Resolve-ReplWorkspaceDirectory {
311:     # A marker-bearing current directory outranks the workspace env vars: ambient
312:     # MCP_WORKSPACE_PATH values leak across workspaces through host processes and
313:     # persistent consoles, and an inherited value must not re-bind marker trust,
314:     # API keys, and session logs to another workspace while the cache directory
315:     # stays local (triage-report-7c84e6437f7b42d0a67fbe32679a686a). This matches
316:     # the plugin hook's Get-PluginStartPath precedence.
317:     $providerLocation = $null
318:     try {
319:         $location = Get-Location
320:         if ($location.Provider.Name -eq 'FileSystem') {
321:             $providerLocation = $location.ProviderPath
322:         }
323:     } catch {
324:         # Fall through to the env and .NET current directory fallbacks.
325:     }
326: 
327:     # Only the PowerShell provider location is trusted for the marker check: the
328:     # process-wide [Environment]::CurrentDirectory can be stale in shared hosts.
329:     if (-not [string]::IsNullOrWhiteSpace($providerLocation) -and
330:         (Test-Path -LiteralPath $providerLocation -PathType Container)) {
331:         try {
332:             if ((Get-Command Find-MarkerFile -ErrorAction SilentlyContinue) -and
333:                 (Find-MarkerFile -StartDir $providerLocation)) {
334:                 return (Resolve-Path -LiteralPath $providerLocation).ProviderPath
335:             }
336:         } catch {
337:             # No marker above the current directory; consult the env fallbacks below.
338:         }
339:     }
340: 
341:     $candidates = @(
342:         $env:MCP_WORKSPACE_PATH,
343:         $env:MCPSERVER_WORKSPACE_PATH,
344:         $env:MCP_WORKSPACE_START_DIR,
345:         $env:CLAUDE_PROJECT_DIR,
346:         $providerLocation,
347:         [Environment]::CurrentDirectory
348:     )
349: 
350:     foreach ($candidate in $candidates) {
351:         if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
352:         if (Test-Path -LiteralPath $candidate -PathType Container) {
353:             return (Resolve-Path -LiteralPath $candidate).ProviderPath
354:         }
355:     }
356: 
357:     return (Get-Location).ProviderPath
358: }
