72:     public void WrongReaders_AreRejected(string fault) =>
73:         Assert.ThrowsAny<XunitException>(() => AssertReaders(
74:             stored => fault switch
75:             {
76:                 "read time" => DateTimeOffset.UtcNow,
77:                 "always null" => null,
