88:                 "year in the text" => YearInTextRead(stored),
89:                 _ => throw new ArgumentOutOfRangeException(nameof(fault)),
90:             },
91:             links => fault switch
92:             {
93:                 "latest link" => links.Select(ScriptedRead).Where(value => value is not null).OrderByDescending(value => value).FirstOrDefault(),
94:                 "date filled from the clock" => links.Select(ClockFillingRead).Where(value => value is not null).Min(),
95:                 "year in the text" => links.Select(YearInTextRead).Where(value => value is not null).Min(),
96:                 _ => ScriptedEarliest(links),
97:             }));
