3: /// <summary>
4: /// TR-MCP-NUKE-019 AC-2: Production <see cref="IIntegrationLaneClassFilter"/>. The host filter alone for a project the
5: /// lane runs whole; otherwise the host filter and, in parentheses ('&amp;' binds tighter than '|'), one
6: /// <c>FullyQualifiedName~.Class.</c> match per class, bounded by dots so it selects that class only.
7: /// </summary>
8: sealed class IntegrationLaneClassFilter : IIntegrationLaneClassFilter
9: {
10:     static readonly Regex PlainIdentifier = new("^[A-Za-z_][A-Za-z0-9_]*\\z", RegexOptions.CultureInvariant);
11: 
12:     /// <inheritdoc />
13:     /// <remarks>
14:     /// <list type="table">
15:     /// <listheader><term>Date</term><description>Requirements; AC; change and reason</description></listheader>
16:     /// <item><term>2026-11-02</term><description>FR-MCP-BUILD-001; TR-MCP-NUKE-019 AC-2; TR-MCP-NUKE-020 AC-3: now built from the shared class clause; the lane filter text is unchanged.</description></item>
17:     /// </list>
18:     /// </remarks>
19:     public string Compose(string hostFilter, IReadOnlyList<string> classNames)
20:     {
21:         ArgumentException.ThrowIfNullOrWhiteSpace(hostFilter);
22:         ArgumentNullException.ThrowIfNull(classNames);
23:         if (classNames.Count == 0)
24:             return hostFilter;
25: 
26:         return $"{hostFilter}&{ClassClause(classNames)}";
27:     }
28: 
29:     /// <summary>
30:     /// TR-MCP-NUKE-019 AC-2 and TR-MCP-NUKE-020 AC-2: the one class clause the lane and the TestGroups target share, in
31:     /// parentheses: one <c>FullyQualifiedName~.Class.</c> match per class, bounded by dots so it selects that class only.
32:     /// </summary>
33:     /// <param name="classNames">One or more plain class names.</param>
34:     /// <returns>The parenthesized clause.</returns>
35:     /// <exception cref="ArgumentException">A name is not a plain class name, or no name is given.</exception>
36:     /// <remarks>
37:     /// <list type="table">
38:     /// <listheader><term>Date</term><description>Requirements; AC; change and reason</description></listheader>
39:     /// <item><term>2026-11-02</term><description>FR-MCP-BUILD-001; TR-MCP-NUKE-019 AC-2; TR-MCP-NUKE-020 AC-2: extracted so the lane and TestGroups select classes with one clause.</description></item>
40:     /// </list>
41:     /// </remarks>
42:     internal static string ClassClause(IReadOnlyList<string> classNames)
43:     {
44:         ArgumentNullException.ThrowIfNull(classNames);
45:         foreach (var name in classNames)
46:         {
47:             if (name is null || !PlainIdentifier.IsMatch(name))
48:                 throw new ArgumentException($"Integration lane class '{name}' is not a plain class name.", nameof(classNames));
49:         }
50: 
51:         if (classNames.Count == 0)
52:             throw new ArgumentException("A class clause needs at least one class name.", nameof(classNames));
53: 
54:         return $"({string.Join("|", classNames.Select(name => $"FullyQualifiedName~.{name}."))})";
55:     }
56: }
