3: /// <summary>
4: /// TR-MCP-USECASE-018 AC-006 (appended "This covers every recorded time a unit test checks, including the creation and
5: /// update times a service stamps on a record it stores: the test supplies the service's clock as scripted times"): a
6: /// test-owned <see cref="TimeProvider"/> handed to a service under test. Each <see cref="GetUtcNow"/> returns the next
7: /// scripted UTC instant, in order; a read past the script is refused, and so are the stopwatch timestamp and timers, so
8: /// the provider never reads or waits on the real clock. Its local time zone is UTC.
9: /// </summary>
10: /// <remarks>
11: /// <list type="table">
12: /// <listheader><term>Date</term><description>Requirements; AC; change and reason</description></listheader>
13: /// <item><term>2026-11-03</term><description>TR-MCP-USECASE-018 AC-006 (appended "This covers every recorded time a unit test checks"): added for the GraphRAG entity and memory timestamp cases, because the sibling sweep before round 11 of hostile validation round 10 finding R10-F3 found three unit cases that compared service-stamped times with the live clock or slept to separate them (operator 2026-11-03: "don't gate on me between rounds"; contract StampedTimeContractTests).</description></item>
14: /// </list>
15: /// </remarks>
16: internal sealed class ScriptedTimeProvider : TimeProvider
17: {
18:     private readonly DateTimeOffset[] _times;
19:     private int _next;
20: 
21:     /// <summary>Creates a provider that returns <paramref name="times"/> in order.</summary>
22:     /// <param name="times">The scripted instants; at least one, each with a zero offset.</param>
23:     /// <exception cref="ArgumentException">No time is given, or a time has a non-zero offset.</exception>
24:     internal ScriptedTimeProvider(params DateTimeOffset[] times)
25:     {
26:         ArgumentNullException.ThrowIfNull(times);
27:         if (times.Length == 0)
28:             throw new ArgumentException("A scripted time provider needs at least one time.", nameof(times));
29:         if (times.Any(time => time.Offset != TimeSpan.Zero))
30:             throw new ArgumentException("A scripted time provider returns UTC instants; every time needs a zero offset.", nameof(times));
31:         _times = times;
32:     }
33: 
34:     /// <summary>The number of reads so far.</summary>
35:     internal int Reads => _next;
36: 
37:     /// <inheritdoc />
38:     public override TimeZoneInfo LocalTimeZone => TimeZoneInfo.Utc;
39: 
40:     /// <summary>Returns the next scripted instant.</summary>
41:     /// <returns>The next time.</returns>
42:     /// <exception cref="InvalidOperationException">Every scripted time has been read.</exception>
43:     public override DateTimeOffset GetUtcNow() =>
44:         _next < _times.Length
45:             ? _times[_next++]
46:             : throw new InvalidOperationException($"The scripted time provider has no time left after {_times.Length} reads.");
47: 
48:     /// <summary>Refused: a scripted provider supplies wall-clock instants only and never reads the stopwatch.</summary>
49:     /// <returns>Never returns.</returns>
50:     /// <exception cref="NotSupportedException">Always.</exception>
51:     public override long GetTimestamp() =>
52:         throw new NotSupportedException("The scripted time provider supplies wall-clock instants only.");
53: 
54:     /// <summary>Refused: a scripted provider never starts a real timer.</summary>
55:     /// <param name="callback">The timer callback.</param>
56:     /// <param name="state">The callback state.</param>
57:     /// <param name="dueTime">The due time.</param>
58:     /// <param name="period">The period.</param>
59:     /// <returns>Never returns.</returns>
60:     /// <exception cref="NotSupportedException">Always.</exception>
61:     public override ITimer CreateTimer(TimerCallback callback, object? state, TimeSpan dueTime, TimeSpan period) =>
62:         throw new NotSupportedException("The scripted time provider never starts a real timer.");
63: }
