356:     private bool TryReadMarker(out MarkerSettings? marker)
357:     {
358:         marker = null;
359:         if (!File.Exists(MarkerPath))
360:         {
361:             return false;
362:         }
363: 
364:         try
365:         {
366:             var values = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
367:             foreach (var rawLine in File.ReadLines(MarkerPath))
368:             {
369:                 var line = rawLine.Trim();
370:                 if (line.Length == 0 || line.StartsWith("#", StringComparison.Ordinal))
371:                 {
372:                     continue;
373:                 }
374: 
375:                 var separator = line.IndexOf(':', StringComparison.Ordinal);
376:                 if (separator <= 0)
377:                 {
378:                     continue;
379:                 }
380: 
381:                 var key = line[..separator].Trim();
382:                 if (key is not ("port" or "baseUrl" or "apiKey" or "workspacePath"))
383:                 {
384:                     continue;
385:                 }
386: 
387:                 values[key] = Unquote(line[(separator + 1)..].Trim());
388:             }
389: 
390:             if (!values.TryGetValue("port", out var rawPort)
391:                 || !int.TryParse(rawPort, NumberStyles.Integer, CultureInfo.InvariantCulture, out var port)
392:                 || !values.TryGetValue("baseUrl", out var baseUrl)
393:                 || string.IsNullOrWhiteSpace(baseUrl)
394:                 || !values.TryGetValue("apiKey", out var apiKey)
395:                 || string.IsNullOrWhiteSpace(apiKey))
396:             {
397:                 return false;
398:             }
399: 
400:             marker = new MarkerSettings(port, baseUrl.TrimEnd('/'), apiKey);
401:             return true;
402:         }
403:         catch (IOException)
404:         {
405:             return false;
406:         }
407:         catch (UnauthorizedAccessException)
408:         {
409:             return false;
410:         }
411:     }
