5: /// <summary>
6: /// TR-MCP-WS-005 / FR-MCP-018 ac-1, TR-MCP-SESSIONLOG-006 / AC-FR-MCP-SESSIONLOGCTX-001-008:
7: /// walks a directory tree under the user profile breadth first without following directory links or other
8: /// reparse points, and skips the contents of any directory whose listing fails with an IO or access error
9: /// (an untrusted mount point, an access-denied or vanished folder), so a scan never fails on what it cannot
10: /// traverse.
11: /// </summary>
12: /// <remarks>
13: /// A directory is yielded when its parent lists it, unless it is a link; its contents are walked only when its own
14: /// listing succeeds. File links are yielded as files. Listing errors other than <see cref="IOException"/> and
15: /// <see cref="UnauthorizedAccessException"/> propagate. A scan root below the user profile or home is walked only
16: /// when <see cref="IsReachable"/> holds for it (hostile validation round 5 finding R5-F1; operator 2026-10-21:
17: /// "Fix both, strengthen ACs").
18: /// </remarks>
19: internal sealed class DirectoryTreeWalker
20: {
21:     private static readonly EnumerationOptions s_singleLevel = new()
22:     {
23:         RecurseSubdirectories = false,
24:         IgnoreInaccessible = false,
25:         AttributesToSkip = 0,
26:         ReturnSpecialDirectories = false,
27:     };
28: 
29:     private readonly Func<string, IReadOnlyList<DirectoryListingEntry>> _list;
30:     private readonly WorkspacePathPlatform? _platform;
31: 
32:     /// <summary>Creates a walker that lists each directory through <paramref name="list"/>.</summary>
33:     /// <param name="list">Lists one directory, or throws when it cannot be listed.</param>
34:     /// <param name="platform">Explicit path policy; when absent the boundary's syntax selects it.</param>
35:     internal DirectoryTreeWalker(Func<string, IReadOnlyList<DirectoryListingEntry>> list, WorkspacePathPlatform? platform = null)
36:     {
37:         ArgumentNullException.ThrowIfNull(list);
38:         _list = list;
39:         _platform = platform;
40:     }
41: 
42:     /// <summary>The walker over the real file system.</summary>
43:     internal static DirectoryTreeWalker FileSystem => new(ListFileSystem,
44:         OperatingSystem.IsWindows() ? WorkspacePathPlatform.Windows : WorkspacePathPlatform.CaseSensitive);
45: 
46:     /// <summary>Every directory below <paramref name="root"/> that the walk reaches.</summary>
47:     /// <param name="root">Directory to walk; it is listed but not yielded.</param>
48:     /// <returns>The reached directories, breadth first.</returns>
49:     internal IEnumerable<string> EnumerateDirectories(string root) => Walk(root, yieldDirectories: true);
50: 
51:     /// <summary>Every file below <paramref name="root"/> that the walk reaches.</summary>
52:     /// <param name="root">Directory to walk.</param>
53:     /// <returns>The reached files, breadth first.</returns>
54:     internal IEnumerable<string> EnumerateFiles(string root) => Walk(root, yieldDirectories: false);
55: 
56:     /// <summary>
57:     /// FR-MCP-018 ac-1, AC-FR-MCP-SESSIONLOGCTX-001-008: whether <paramref name="root"/> may be walked from
58:     /// <paramref name="boundary"/>: the root and every folder between the boundary and it must each be listed by
59:     /// its parent as a directory that is not a link or other reparse point. The boundary itself is trusted (a user
60:     /// profile or home that is itself a link is still scanned) and its parent is never listed; a root that is the
61:     /// boundary is reachable without any listing.
62:     /// </summary>
63:     /// <remarks>
64:     /// A folder whose listing fails with an <see cref="IOException"/> or <see cref="UnauthorizedAccessException"/>
65:     /// cannot be traversed, so the root is not reachable; any other listing error propagates. A root that is not
66:     /// below the boundary, or that a parent does not list as a directory, is not reachable.
67:     /// </remarks>
68:     /// <param name="boundary">The trusted folder the scan starts from (the user profile or home).</param>
69:     /// <param name="root">The scan root below <paramref name="boundary"/>.</param>
70:     /// <returns>True when the root may be walked.</returns>
71:     internal bool IsReachable(string boundary, string root)
72:     {
73:         ArgumentNullException.ThrowIfNull(boundary);
74:         ArgumentNullException.ThrowIfNull(root);
75:         var platform = _platform ?? WorkspaceIdentityPath.DetectPlatform(boundary);
76:         var comparison = platform == WorkspacePathPlatform.Windows ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
77:         string Canonical(string path) => WorkspaceIdentityPath.NormalizeLexicalPath(path, platform);
78:         var target = Canonical(root);
79:         var current = Canonical(boundary);
80:         while (!string.Equals(current, target, comparison))
81:         {
82:             IReadOnlyList<DirectoryListingEntry> entries;
83:             try
84:             {
85:                 entries = _list(current);
86:             }
87:             catch (IOException)
88:             {
89:                 return false;
90:             }
91:             catch (UnauthorizedAccessException)
92:             {
93:                 return false;
94:             }
95: 
96:             var found = entries
97:                 .Select(entry => entry with { Path = Canonical(entry.Path) })
98:                 .Where(entry => LeadsTo(entry.Path, target, comparison))
99:                 .Select(entry => (DirectoryListingEntry?)entry)
100:                 .FirstOrDefault();
101:             if (found is not { } next || !next.IsDirectory || next.IsLink || next.Path.Length <= current.Length)
102:                 return false;
103:             current = next.Path;
104:         }
105: 
106:         return true;
107:     }
108: 
109:     /// <summary>True when <paramref name="path"/> is <paramref name="target"/> or a folder above it.</summary>
110:     private static bool LeadsTo(string path, string target, StringComparison comparison) =>
111:         target.StartsWith(path, comparison)
112:         && (target.Length == path.Length
113:             || path.EndsWith('/')
114:             || target[path.Length] == '/');
115: 
116:     /// <summary>Lists one real directory with each entry's directory and link flags.</summary>
117:     /// <param name="directory">Directory to list.</param>
118:     /// <returns>The entries of <paramref name="directory"/>.</returns>
119:     internal static IReadOnlyList<DirectoryListingEntry> ListFileSystem(string directory) =>
120:         new DirectoryInfo(directory)
121:             .EnumerateFileSystemInfos("*", s_singleLevel)
122:             .Select(info => new DirectoryListingEntry(
123:                 info.FullName,
124:                 info is DirectoryInfo,
125:                 (info.Attributes & FileAttributes.ReparsePoint) != 0))
126:             .ToList();
