5: $root=Get-Location
6: $receiptRoot=Join-Path $root 'docs/receipts/hv'
7: $runRoot=Join-Path $root 'docs/receipts/unit-suite-green-20261019'
8: function Read-JsonDocument { param([string]$Path) Get-Content -LiteralPath $Path -Raw|ConvertFrom-Json -Depth 100 -DateKind String }
9: function Get-ResultName {
10:  param([string[]]$Paths)
11:  $rows=[System.Collections.Generic.List[string]]::new()
12:  foreach($path in $Paths) {
13:   $xml=[xml][IO.File]::ReadAllText($path)
14:   foreach($result in $xml.SelectNodes('//*[local-name()="UnitTestResult"]')) { $rows.Add([string]$result.testName) }
15:  }
16:  return ,$rows.ToArray()
17: }
18: function Compare-NameMultiset {
19:  param([string]$Label,[string[]]$Before,[string[]]$After)
20:  $left=[System.Collections.Generic.Dictionary[string,int]]::new([StringComparer]::Ordinal)
21:  $right=[System.Collections.Generic.Dictionary[string,int]]::new([StringComparer]::Ordinal)
22:  foreach($name in $Before) { $left[$name]++ }
23:  foreach($name in $After) { $right[$name]++ }
24:  $lost=@(foreach($name in $left.Keys) { if($left[$name] -gt $right[$name]) { [pscustomobject]@{name=$name;count=($left[$name]-$right[$name])} } })
25:  $added=@(foreach($name in $right.Keys) { if($right[$name] -gt $left[$name]) { [pscustomobject]@{name=$name;count=($right[$name]-$left[$name])} } })
26:  [pscustomobject]@{label=$Label;beforeRows=$Before.Count;afterRows=$After.Count;beforeNames=$left.Count;afterNames=$right.Count;lost=$lost;added=$added}
27: }
28: $manifest=Read-JsonDocument (Join-Path $receiptRoot 'unitgreen-r11-trx-1f51d4b2/manifest.json')
29: $current=@{}
