325:     /// letter, or "server/share") and its segments after the root, split on either separator. UNC and drive-letter paths
326:     /// are Windows syntax and compare ignoring case; POSIX paths compare ordinally. Two paths share a location only under
327:     /// the same root kind and root identity.
328:     /// </summary>
329:     /// <param name="Kind">The root kind.</param>
330:     /// <param name="Root">The root identity.</param>
331:     /// <param name="Segments">The segments after the root.</param>
332:     /// <remarks>
333:     /// <list type="table">
334:     /// <listheader><term>Date</term><description>Requirements; AC; change and reason</description></listheader>
335:     /// <item><term>2026-11-03</term><description>FR-MCP-TESTRESOURCE-001 ac-4 (appended "Strict containment in the owned root also requires the same root") and the generated-artifact criterion (appended "A path's root is part of its identity"): added, replacing the segment split that dropped the root and the Windows-form test that missed forward-slash UNC paths, because hostile validation round 10 finding R10-F2 showed a single-rooted path was accepted under a UNC owned root and a forward-slash UNC alias of the checkout was compared ordinally (operator 2026-11-03: "don't gate on me between rounds"). Follows the repository's own reading of "//" as UNC (WorkspaceIdentityPath).</description></item>
336:     /// </list>
337:     /// </remarks>
338:     private readonly record struct PathIdentity(PathRootKind Kind, string Root, string[] Segments)
339:     {
340:         /// <summary>How this path's root and segments compare: ignoring case for Windows syntax, ordinally for POSIX.</summary>
341:         internal StringComparison Comparison => Kind is PathRootKind.Drive or PathRootKind.Unc ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
342: 
343:         /// <summary>Parses a path into its root and segments.</summary>
344:         /// <param name="path">The path.</param>
345:         /// <returns>The identity; kind None when the path is not absolute.</returns>
346:         internal static PathIdentity Parse(string path)
347:         {
348:             if (path.Length > 2 && IsSeparator(path[0]) && IsSeparator(path[1]) && !IsSeparator(path[2]))
349:             {
350:                 var parts = Split(path[2..]);
351:                 return parts.Length >= 2 ? new PathIdentity(PathRootKind.Unc, parts[0] + "/" + parts[1], parts[2..]) : new PathIdentity(PathRootKind.None, string.Empty, []);
352:             }
353: 
354:             if (path.Length >= 3 && char.IsAsciiLetter(path[0]) && path[1] == ':' && IsSeparator(path[2]))
355:                 return new PathIdentity(PathRootKind.Drive, path[..1], Split(path[3..]));
356:             return path.StartsWith('/')
357:                 ? new PathIdentity(PathRootKind.Posix, "/", Split(path[1..]))
358:                 : new PathIdentity(PathRootKind.None, string.Empty, []);
359:         }
360: 
361:         /// <summary>Whether another identity has the same root kind and root identity.</summary>
362:         /// <param name="other">The other identity.</param>
363:         /// <returns>True for the same root.</returns>
364:         internal bool SameRoot(PathIdentity other) =>
365:             Kind != PathRootKind.None && Kind == other.Kind && string.Equals(Root, other.Root, Comparison);
366: 
367:         /// <summary>Whether another identity names the same location: the same root and the same segments.</summary>
368:         /// <param name="other">The other identity.</param>
369:         /// <returns>True for the same location.</returns>
370:         internal bool SameLocation(PathIdentity other)
371:         {
372:             var comparison = Comparison;
373:             return SameRoot(other) && Segments.Length == other.Segments.Length
374:                 && Segments.Zip(other.Segments).All(pair => string.Equals(pair.First, pair.Second, comparison));
375:         }
376: 
377:         /// <summary>Whether a character is a path separator of either kind.</summary>
378:         /// <param name="value">The character.</param>
379:         /// <returns>True for '/' or '\'.</returns>
380:         private static bool IsSeparator(char value) => value is '/' or '\\';
381: 
382:         /// <summary>The non-empty parts of a text split on either separator.</summary>
383:         /// <param name="text">The text after the root.</param>
384:         /// <returns>The parts.</returns>
385:         private static string[] Split(string text) => text.Split(['/', '\\'], StringSplitOptions.RemoveEmptyEntries);
386:     }
