63:     {
64:         var requestType = request.GetType();
65:         var context = new CallContext { OperationName = requestType.Name, CancellationToken = ct };
66:         _activeContexts[context.Correlation.BaseId] = context;
67:         var outcome = "Unknown";
68:         string? error = null;
