70: 
71:         var sw = Stopwatch.StartNew();
72:         try
73:         {
74:             _logger.LogDebug(
75:                 "Dispatching {Operation} [{CorrelationId}]",
76:                 context.OperationName, context.Correlation.Current);
77: 
78:             // Apply timeout if the request implements IHasTimeout
79:             var effectiveCt = ct;
80:             CancellationTokenSource? timeoutCts = null;
81:             if (request is IHasTimeout hasTimeout)
82:             {
83:                 timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
84:                 timeoutCts.CancelAfter(hasTimeout.Timeout);
85:                 effectiveCt = timeoutCts.Token;
86:                 context.CancellationToken = effectiveCt;
87:             }
88: 
89:             try
90:             {
91:                 // Resolve handler
92:                 var handlerType = handlerOpenType.MakeGenericType(requestType, typeof(TResult));
93:                 var handler = _services.GetRequiredService(handlerType);
94: 
95:                 // Build pipeline: behaviors wrap the handler invocation
96:                 var behaviors = _services.GetServices<IPipelineBehavior>().ToList();
97: 
98:                 // The innermost delegate calls the handler
99:                 Func<Task<Result<TResult>>> innermost = () => InvokeHandler<TResult>(handler, handlerType, request, context);
100: 
101:                 // Wrap with behaviors (outermost first = first registered)
102:                 var pipeline = innermost;
103:                 for (var i = behaviors.Count - 1; i >= 0; i--)
104:                 {
105:                     var behavior = behaviors[i];
106:                     var next = pipeline;
107:                     pipeline = () => behavior.HandleAsync(request, context, next);
108:                 }
109: 
110:                 var result = await pipeline().ConfigureAwait(true);
111: 
112:                 sw.Stop();
113:                 LogResult(result, context, sw.Elapsed);
114:                 outcome = result.IsSuccess ? "Success" : "Failure";
115:                 error = result.Error;
116:                 context.Properties["ResultData"] = result.ToString();
117:                 return result;
118:             }
